/**
 * Generates supabase/seed.sql from the publications mock — the same
 * BUSINESSES/PROPERTIES/LISTINGS/… arrays the /listings endpoints serve, so
 * the DB is a straight row copy of src/data (docs/informe-mock-listings §6).
 *
 *   cd apps/api && ./node_modules/.bin/tsx scripts/gen-seed.ts > ../../supabase/seed.sql
 *
 * Availability is generated by the same deterministic buildAvailability() the
 * repo uses — the night window rolls from "today", so regenerate to freshen.
 */
import { buildAvailability } from "../src/data/availability.js";
import { AMENITIES } from "../src/data/catalog.js";
import {
  BUSINESSES,
  LISTINGS,
  LISTING_AMENITIES,
  LISTING_PHOTOS,
  LISTING_UNITS,
  PROPERTIES,
  RATE_RULES,
} from "../src/data/inventory.js";

type Val = string | number | boolean | null | undefined;
const q = (v: Val) =>
  v == null
    ? "null"
    : v === true
      ? "true"
      : v === false
        ? "false"
        : typeof v === "number"
          ? String(v)
          : `'${v.replace(/'/g, "''")}'`;

const insert = (
  table: string,
  cols: string[],
  rows: Val[][],
  chunkSize = 100
) => {
  const out: string[] = [];
  for (let i = 0; i < rows.length; i += chunkSize) {
    const chunk = rows
      .slice(i, i + chunkSize)
      .map((r) => `(${r.map(q).join(",")})`)
      .join(",\n");
    out.push(
      `insert into public.${table} (${cols.join(",")}) values\n${chunk}\non conflict do nothing;`
    );
  }
  return out.join("\n\n");
};

const lines: string[] = [
  "-- nomai seed — publications inventory, a straight row copy of",
  "-- apps/api/src/data. Regenerate:",
  "--   tsx apps/api/scripts/gen-seed.ts > supabase/seed.sql",
  "-- Idempotent (on conflict do nothing). Availability covers ~90 days from",
  "-- generation time — rerun to freshen the bookable window.",
  "",
];

lines.push(
  insert(
    "businesses",
    ["id","name","slug","legal_name","tax_id","payout_address","email","phone","status","created_at","updated_at"],
    BUSINESSES.map((b) => [b.id,b.name,b.slug,b.legal_name,b.tax_id,b.payout_address,b.email,b.phone,b.status,b.created_at,b.updated_at])
  ),
  "",
  insert(
    "properties",
    ["id","business_id","name","property_type","description","address_line1","city","region","country_code","postal_code","latitude","longitude","timezone","checkin_time","checkout_time","created_at","updated_at"],
    PROPERTIES.map((p) => [p.id,p.business_id,p.name,p.property_type,p.description,p.address_line1,p.city,p.region,p.country_code,p.postal_code,p.latitude,p.longitude,p.timezone,p.checkin_time,p.checkout_time,p.created_at,p.updated_at])
  ),
  "",
  insert(
    "listings",
    ["id","property_id","slug","title","summary","description","kind","max_guests","bedrooms","beds","bathrooms","base_price_minor","currency","cleaning_fee_minor","min_nights","max_nights","rating","reviews","instant_book","pets_allowed","smoking_allowed","events_allowed","status","published_at","created_at","updated_at"],
    LISTINGS.map((l) => [l.id,l.property_id,l.slug,l.title,l.summary,l.description,l.kind,l.max_guests,l.bedrooms,l.beds,l.bathrooms,l.base_price_minor,l.currency,l.cleaning_fee_minor,l.min_nights,l.max_nights,l.rating,l.reviews,l.instant_book,l.pets_allowed,l.smoking_allowed,l.events_allowed,l.status,l.published_at,l.created_at,l.updated_at])
  ),
  "",
  insert(
    "amenities",
    ["id","code","name","category"],
    AMENITIES.map((a) => [a.id,a.code,a.name,a.category])
  ),
  "",
  insert(
    "listing_amenities",
    ["listing_id","amenity_id","detail"],
    LISTING_AMENITIES.map((a) => [a.listing_id,a.amenity_id,a.detail])
  ),
  "",
  insert(
    "listing_photos",
    ["id","listing_id","url","alt_text","position","is_cover"],
    LISTING_PHOTOS.map((p) => [p.id,p.listing_id,p.url,p.alt_text,p.position,p.is_cover])
  ),
  "",
  insert(
    "listing_units",
    ["id","listing_id","code","status"],
    LISTING_UNITS.map((u) => [u.id,u.listing_id,u.code,u.status])
  ),
  "",
  insert(
    "rate_rules",
    ["id","listing_id","name","start_date","end_date","nightly_price_minor","min_nights","priority"],
    RATE_RULES.map((r) => [r.id,r.listing_id,r.name,r.start_date,r.end_date,r.nightly_price_minor,r.min_nights,r.priority])
  ),
  "",
  insert(
    "availability_nights",
    ["listing_id","night","status","units_available","price_minor"],
    buildAvailability(new Date()).map((a) => [a.listing_id,a.night,a.status,a.units_available,a.price_minor]),
    400
  ),
  ""
);

console.log(lines.join("\n"));
